def overall_run_stats(batsman_data: dict):
    all_runs = [r for runs in batsman_data.values() for r in runs]
    total = sum(all_runs)
    return {
        "min": min(all_runs),
        "max": max(all_runs),
        "total": total,
        "average": round(total / len(all_runs)),
    }

def century_rate(runs: list):
    centuries = sum(1 for r in runs if r >= 100)
    return round(centuries / len(runs) * 100)

def average_yearly_century_rate(batsman_data: dict):
    rates = [century_rate(runs) for runs in batsman_data.values()]
    return round(sum(rates) / len(rates))

def years_with_more_than_average_yearly_century_rate(batsman_data: dict):
    avg = average_yearly_century_rate(batsman_data)
    return {year for year, runs in batsman_data.items() if century_rate(runs) > avg}

def year_with_most_average_runs(batsman_data: dict):
    best_year = None
    best_avg = None
    # Iterate years in ascending order so ties keep the earliest year.
    for year in sorted(batsman_data):
        avg = sum(batsman_data[year]) / len(batsman_data[year])
        if best_avg is None or avg > best_avg:
            best_avg = avg
            best_year = year
    return best_year

def double_ends(l):
    # Build a brand-new list so the original stays untouched.
    return [l[0]] + list(l) + [l[-1]]

def extract_email_username(email):
    # Everything before the single '@' is the username.
    return email.split("@")[0]
